use vstd::prelude::*;

verus! {
    // Given two equal‐length vectors of i8, produce a bool vector
    // where each entry says whether a[i] > b[i] (promoted to i32).
    fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            // For every valid index i, result[i] is exactly (a[i] as i32) > (b[i] as i32).
            forall |i: usize| i < a.len() ==> result[i] == ((a[i] as i32) > (b[i] as i32)),
    {
        let n = a.len();
        // We allocate a result vector with capacity n to avoid re‐allocation.
        let mut res: Vec<bool> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                // i never exceeds the length
                i <= n,
                // we've pushed exactly i entries so far
                res.len() == i,
                // and they all satisfy the specification
                forall |j: usize| j < i ==>
                    res[j] == ((a[j] as i32) > (b[j] as i32)),
            decreases n - i,
        {
            let ai: i8 = a[i];
            let bi: i8 = b[i];
            let cmp: bool = (ai as i32) > (bi as i32);
            res.push(cmp);
            i += 1;
        }
        res
    }
}

